#!/usr/bin/env sh
# @NAME@ launcher generated by the emuStudio build. JVM options: JAVA_OPTS, @OPTS@.

PRG=$0
while [ -h "$PRG" ]; do
    link=$(ls -ld "$PRG" | sed 's/.*-> //')
    case $link in
        /*) PRG=$link ;;
        *) PRG=$(dirname "$PRG")/$link ;;
    esac
done
APP_HOME=$(cd "$(dirname "$PRG")/.." > /dev/null && pwd -P) || exit

JAVACMD=java
if [ -n "$JAVA_HOME" ]; then
    JAVACMD=$JAVA_HOME/bin/java
fi

exec "$JAVACMD" $JAVA_OPTS $@OPTS@ -classpath "@CLASSPATH_SH@" @MAIN_CLASS@ "$@"
